function SweepQuestRewardsCell:RefreshUI(index , data , isGuang , count)
    ---@type CommonGoodsList
    local RewardGroup = self.RewardGroup.Env
    RewardGroup:FreshBaseUI(data)
    CfUtils.FillText(self.TxtTitle.gameObject , localize("第_num_轮奖励", {_num_ = index +1}))
    if (not isGuang) then
        self.co = cs_coroutine.start(function()
            self.controller.gameObject:SetActive(false)
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 0.1*(3 -(count - index)) ))
            self.controller.gameObject:SetActive(true)
            self.RewardAnimNode.gameObject:SetActive(true)
        end)
    else
        self.RewardAnimNode.gameObject:SetActive(false)
    end
end

